/*\
title: $:/plugins/maans/plato/video-export.js
type: application/javascript
module-type: startup
\*/
(function(){
"use strict";
// Turn Around keeps its native film and its recorded takes as the single source
// of truth. This optional adapter only connects its audience view to the shared
// AniMus exporter; it does not replace the player or modify project tiddlers.
exports.name="plato-animus-video-export";
exports.platforms=["browser"];
exports.after=["startup"];
exports.synchronous=true;
exports.startup=function(){
 var Runtime,Engine;
 try{
  Runtime=require("$:/plugins/huwiki/animus-video-export/runtime.js");
  Engine=require("$:/plugins/huwiki/cutout/engine.js");
 }catch(_optionalExport){return;}
 if(!Runtime||!Runtime.attach||typeof document==="undefined"||!document.body)return;
 var doc=document,win=doc.defaultView||window,active=new Map(),observer=null;
 function gain(host,kind){
  // The audience player routes recorded effects through its Music bus.
  var label=kind==="speech"?"Speech":kind==="song"?"Singing":"Music";
  var slider=host.querySelector('.plato-level[aria-label="'+label+', volume"]');
  var value=slider?Number(slider.value):1;
  return Number.isFinite(value)?Math.max(0,Math.min(1,value)):1;
 }
 function scene(host,player){
  var timeline=player.getTimeline(),film=Engine.readScene($tw.wiki,timeline.filmTitle);
  if(!film)throw Error("Turn Around's native AniMus film is unavailable");
  var musical=Object.assign({},film.musical||{});
  musical.audioClips=timeline.audioClips.map(function(clip){
   var copy=Object.assign({},clip),volume=Number(clip.volume);
   copy.volume=(Number.isFinite(volume)?volume:1)*gain(host,clip.kind);
   return copy;
  });
  return Object.assign({},film,{name:timeline.title||film.name,musical:musical});
 }
 function remove(host){
  var entry=active.get(host);if(!entry)return;
  active.delete(host);
  if(entry.player.destroy===entry.destroy)entry.player.destroy=entry.originalDestroy;
  if(entry.exporter&&entry.exporter.dispose)entry.exporter.dispose();
 }
 function connect(host){
  if(active.has(host))return;
  var player=host._platoPlayer;
  if(!player||!player.getTimeline||!player.seek||!player.pause||!player.time)return;
  var stage=host.querySelector(".plato-screen"),controls=host.querySelector(".plato-options");
  if(!stage||!controls)return;
  var options={host:host,stage:stage,controls:controls,wiki:$tw.wiki,
   seek:function(t){return player.seek(t);},pause:function(){return player.pause();},
   position:function(){return player.time();},duration:function(){return player.getTimeline().duration;},
   // This player hears the recorded music takes, not the muted ABC guide scores.
   // Rendering those scores again would double the accompaniment.
   getSongs:function(){return [];},getABC:function(){return null;}
  };
  Object.defineProperty(options,"scene",{get:function(){return scene(host,player);}});
  var exporter=Runtime.attach(options);if(!exporter)return;
  var entry={player:player,exporter:exporter,originalDestroy:player.destroy,destroy:null};
  if(typeof player.destroy==="function"){
   entry.destroy=function(){var original=entry.originalDestroy;remove(host);return original.apply(this,arguments);};
   player.destroy=entry.destroy;
  }
  active.set(host,entry);
 }
 function scan(root){
  if(!root)return;
  if(root.nodeType===1&&root.matches&&root.matches(".plato-player"))connect(root);
  if(root.querySelectorAll)Array.prototype.forEach.call(root.querySelectorAll(".plato-player"),connect);
 }
 function changed(records){
  active.forEach(function(entry,host){if(!doc.body.contains(host)||host._platoPlayer!==entry.player)remove(host);});
  records.forEach(function(record){Array.prototype.forEach.call(record.addedNodes||[],scan);});
 }
 if(win.MutationObserver){observer=new win.MutationObserver(changed);observer.observe(doc.body,{childList:true,subtree:true});}
 scan(doc.body);
 return {dispose:function(){if(observer)observer.disconnect();active.forEach(function(_entry,host){remove(host);});}};
};
})();
